#!/usr/bin/env bash
# Reproducer for the diff-engine findings in docs/audit/2026-10-21-audit.md.
#
# Writes a temporary integration test, runs it with --nocapture so the observed
# behavior is printed, then removes it. All probes print "OBSERVED ..." lines;
# the script fails only if a probe panics outside its own catch_unwind harness.
set -euo pipefail

repo_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$repo_root"

probe=tests/zz_audit_diff_probe.rs
cleanup() { rm -f "$probe"; }
trap cleanup EXIT

cat >"$probe" <<'RUST'
//! Temporary probe generated by scripts/audit-diff-probe.sh.
use std::panic::{catch_unwind, AssertUnwindSafe};

use bbr::diff::parser::{filter_raw_diff, parse, parse_diff_git_paths};
use bbr::diff::renderer::{render, DiffRenderOptions, RenderMode};
use bbr::diff::{parse_file_selectors, render_raw_from_files, select_files};
use bbr::output::theme::Theme;

fn print_lines(files: &[bbr::diff::parser::DiffFile]) {
    for f in files {
        println!(
            "  file status={:?} old={:?} new={:?} binary={} hunks={} +{} -{}",
            f.status,
            f.old_path,
            f.new_path,
            f.binary,
            f.hunks.len(),
            f.additions,
            f.deletions
        );
        for (hi, h) in f.hunks.iter().enumerate() {
            println!("    hunk[{hi}] lines={}", h.lines.len());
            for l in &h.lines {
                println!(
                    "      kind={:?} old={:?} new={:?} content={:?}",
                    l.kind, l.old_lineno, l.new_lineno, l.content
                );
            }
        }
    }
}

#[test]
fn probe_1_deleted_sql_comment_is_misread_as_file_header() {
    println!("\nPROBE 1: deletion line whose content starts with \"-- \"");
    let raw = "diff --git a/q.sql b/q.sql\n\
               --- a/q.sql\n\
               +++ b/q.sql\n\
               @@ -1,2 +1,2 @@\n \
               SELECT 1;\n\
               --- old sql comment\n\
               +SELECT 2;\n";
    let files = parse(raw);
    print_lines(&files);
}

#[test]
fn probe_2_context_line_that_looks_like_a_hunk_header() {
    println!("\nPROBE 2: context line whose content is \"@@ -9,9 +9,9 @@\"");
    let raw = "diff --git a/doc.md b/doc.md\n\
               --- a/doc.md\n\
               +++ b/doc.md\n\
               @@ -1,3 +1,3 @@\n \
               context before\n \
               @@ -9,9 +9,9 @@\n \
               context after\n";
    let files = parse(raw);
    print_lines(&files);
}

#[test]
fn probe_3_path_component_named_b() {
    println!("\nPROBE 3: unquoted git header with a directory named b/");
    let (old, new) = parse_diff_git_paths("diff --git a/x b/b/y");
    println!("  OBSERVED old={old:?} new={new:?} (expected new == \"b/y\")");
}

#[test]
fn probe_4_empty_added_file_is_binary() {
    println!("\nPROBE 4: empty file added (git emits no ---/+++ lines)");
    let raw = "diff --git a/empty.txt b/empty.txt\n\
               new file mode 100644\n\
               index 0000000..e69de29\n";
    let files = parse(raw);
    print_lines(&files);
}

#[test]
fn probe_5_file_selection_then_pathspec_filter_is_empty() {
    println!("\nPROBE 5: --file 1 followed by a pathspec");
    let raw = "diff --git a/a.rs b/a.rs\n\
               --- a/a.rs\n\
               +++ b/a.rs\n\
               @@ -1,1 +1,1 @@\n\
               -foo\n\
               +bar\n\
               diff --git a/b.rs b/b.rs\n\
               --- a/b.rs\n\
               +++ b/b.rs\n\
               @@ -1,1 +1,1 @@\n\
               -old\n\
               +new\n";
    let files = parse(raw);
    let selectors = parse_file_selectors(&["1".to_string()]);
    let selected = select_files(&files, &selectors);
    let rebuilt = render_raw_from_files(&selected);
    let filtered = filter_raw_diff(&rebuilt, &["a.rs".to_string()]);
    println!(
        "  OBSERVED selected={} rebuilt_has_diff_git={} filtered_bytes={} filtered_has_bar={}",
        selected.len(),
        rebuilt.contains("diff --git"),
        filtered.len(),
        filtered.contains("+bar")
    );
}

#[test]
fn probe_6_context_usize_max_overflows() {
    println!("\nPROBE 6: --context usize::MAX in the renderer");
    let raw = "diff --git a/f b/f\n--- a/f\n+++ b/f\n@@ -1,1 +1,2 @@\n-a\n+b\n+c\n";
    let files = parse(raw);
    let options = DiffRenderOptions {
        context_lines: usize::MAX,
        mode: RenderMode::Unified,
        word_diff: true,
        syntax_highlight: false,
        wrap_long_lines: false,
    };
    let result = catch_unwind(AssertUnwindSafe(|| {
        let _ = render(&files, &options, Theme::current());
    }));
    println!("  OBSERVED panic={}", result.is_err());
}

#[test]
fn probe_7_hunk_line_counter_overflows() {
    println!("\nPROBE 7: hunk start at u32::MAX plus one body line");
    let raw = "diff --git a/f b/f\n--- a/f\n+++ b/f\n@@ -4294967295,1 +0,0 @@\n-a\n";
    let result = catch_unwind(AssertUnwindSafe(|| {
        let files = parse(raw);
        println!("  parsed files={}", files.len());
    }));
    println!("  OBSERVED panic={}", result.is_err());
}

#[test]
fn probe_8_invalid_file_selector_is_silently_ignored() {
    println!("\nPROBE 8: --file 0");
    let raw = "diff --git a/a.rs b/a.rs\n--- a/a.rs\n+++ b/a.rs\n@@ -1,1 +1,1 @@\n-a\n+b\n";
    let files = parse(raw);
    let selectors = parse_file_selectors(&["0".to_string()]);
    let selected = select_files(&files, &selectors);
    println!(
        "  OBSERVED selectors={} selected={} (empty selector list means 'show all')",
        selectors.len(),
        selected.len()
    );
}
RUST

cargo test --quiet --test zz_audit_diff_probe -- --nocapture --test-threads=1
